maze = []
with open('maze.txt') as f:
    for line in f:
        maze.append(list(line.strip()))

# check all possible wall removals to see which one creates the shortest path
start = None
end = None
for r, row in enumerate(maze):
    for c, val in enumerate(row):
        if val == '@':
            start = (r, c)
        elif val == 'E':
            end = (r, c)

def shortest_path(maze_grid):
    queue = collections.deque([(start, [])])
    visited = set([start])
    while queue:
        (r, c), path = queue.popleft()
        if (r, c) == end:
            return path
        for dr, dc, dname in [(-1, 0, 'up'), (1, 0, 'down'), (0, -1, 'left'), (0, 1, 'right')]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(maze_grid) and 0 <= nc < len(maze_grid[0]):
                if maze_grid[nr][nc] != '#' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + [dname]))
    return None

import copy
best_path = None
best_wall = None
for r in range(len(maze)):
    for c in range(len(maze[0])):
        if maze[r][c] == '#':
            maze_copy = copy.deepcopy(maze)
            maze_copy[r][c] = '.'
            path = shortest_path(maze_copy)
            if path is not None:
                if best_path is None or len(path) < len(best_path):
                    best_path = path
                    best_wall = (r, c)

print('Best wall:', best_wall)
print('Path length:', len(best_path))
