import sys
from collections import deque

with open('maze.txt', 'r') as f:
    maze = [list(line.strip()) for line in f if line.strip()]

start = None
end = None
for r in range(len(maze)):
    for c in range(len(maze[r])):
        if maze[r][c] == '@':
            start = (r, c)
        elif maze[r][c] == 'E':
            end = (r, c)

def bfs(start_pos, target_pos, maze_map):
    q = deque([(start_pos, [])])
    visited = set([start_pos])
    dirs = {
        'up': (-1, 0),
        'down': (1, 0),
        'left': (0, -1),
        'right': (0, 1)
    }
    while q:
        (r, c), path = q.popleft()
        if (r, c) == target_pos:
            return path
        for dname, (dr, dc) in dirs.items():
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(maze_map) and 0 <= nc < len(maze_map[0]):
                if maze_map[nr][nc] != '#' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append(((nr, nc), path + [dname]))
    return None

print(bfs(start, end, maze))
