def get_reachable(start_pos, maze_map):
    q = deque([start_pos])
    visited = set([start_pos])
    dirs = {
        'up': (-1, 0),
        'down': (1, 0),
        'left': (0, -1),
        'right': (0, 1)
    }
    while q:
        r, c = q.popleft()
        for dname, (dr, dc) in dirs.items():
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(maze_map) and 0 <= nc < len(maze_map[0]):
                if maze_map[nr][nc] != '#' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
    return visited

