            if 0 <= nr < len(maze_grid) and 0 <= nc < len(maze_grid[0]):
                if maze_grid[nr][nc] != '#' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc, path + [move]))
    return None

def get_reachable(maze_grid, start_node):
